function StoreExchange:RefreshData()
    
    local cnt = table.count(self.CurrencyDatas)
    KTool.SetActive(self.GoodNode.gameObject, false)
    KTool.SetActive(self.Tips.gameObject, cnt == 0)
    SetButtonAction(self.BtnExchange, function()
        if table.count(self.CurrencyDatas) > 0 then
            GameUtils.SecondConfirm(localize("是否确认兑换"), function()
                GameUtils.Request(Interfaces.StoreExchange,{}, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        GoodsUtils.DrawRewards(response.data.rewards)
                        --for i = 1, 3 do
                        --    local nameKey = "LoopView"..tostring(i)
                        --    GoodsUtils.ConsumeGoods(self.FragDatas[nameKey], true)
                        --end
                        GoodsUtils.ConsumeGoods(self.FragDatas, true)
                        
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards } })

                        self.controller:Close()


                        Events.Broadcast(StoreConstants.StoreEvents.OnFragsRefresh)

                    end
                    
                end)
            end)
        end
    end)
    if cnt == 0 then
        self.BtnExchange.interactable = false
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(Currency)
        CfUtils.FillImage(self.ImgIcon, goodsVo.photoPath)
        CfUtils.FillImage(self.ImgFrame, StoreUtils.GetGoodsBgByQuality(goodsVo.quality))
        CfUtils.FillText(self.TxtName, goodsVo.name)
        local num = GoodsUtils.GetThingNo(Currency)
        CfUtils.FillText(self.TxtNumber1, num)
        CfUtils.FillText(self.TxtNumber2, num)
    else
        local currencyData = self.CurrencyDatas[1]
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(currencyData.goodsId)
        CfUtils.FillImage(self.ImgIcon, goodsVo.photoPath)
        CfUtils.FillImage(self.ImgFrame, StoreUtils.GetGoodsBgByQuality(goodsVo.quality))
        CfUtils.FillText(self.TxtName, goodsVo.name)
        local num = GoodsUtils.GetThingNo(currencyData.goodsId)
        CfUtils.FillText(self.TxtNumber1, num)
        CfUtils.FillText(self.TxtNumber2, num + currencyData.goodsNum)
        
        local fragCnt = #self.FragDatas
        --self.LoopView:InitGridView(cnt, Bind(self, self.OnItemEntryRefresh))
        self.LoopView1:InitGridView(fragCnt, Bind(self, self.OnFragRefresh))
        --print(table.dump(self.FragDatas))
        
    end
    
end

function StoreExchange:IndexOfData(tableData, goodsId)
    if tableData == nil then
        return false
    end

    local data 
    for i = 1, #tableData do
        if tableData[i].goodsId == goodsId then
            data = tableData[i]
            break;
        end
    end
    
    return data
end

function StoreExchange:SelectData()
    if self.CurrencyDatas == nil then
        self.CurrencyDatas = {}
    end
    --if self.FragDatas == nil then
    --    self.FragDatas = {}
    --end
    local frags = StoreUtils.GetAllExchangeFrags()
    for i, v in ipairs(frags) do
        local consume = v
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(consume.goodsId)
        --if self.FragDatas[vo.effectId] == nil then
        --    self.FragDatas[vo.effectId] = {}
        --end
        --table.insert(self.FragDatas[vo.effectId], consume)
        local data = self:IndexOfData(self.CurrencyDatas, vo.effectId)
        if not data then
            table.insert(self.CurrencyDatas, {
                goodsId = vo.effectId,
                goodsNum = vo.effectNum * consume.goodsNum
            })
        else
            data.goodsNum = data.goodsNum + vo.effectNum * consume.goodsNum
        end
    end

    self.FragDatas = frags

    table.sort(self.CurrencyDatas, function(a, b)
        return a.goodsId > b.goodsId
    end)
    
    print(table.dump(self.FragDatas))

    --for k,v in pairs(self.FragDatas) do
    --    print(table.dump(v))
    --end
end

function StoreExchange:RefreshGoodNode(trans, data)
    if KTool.IsActiveInHierarchy(trans.gameObject) then
        KTool.SetActive(trans.gameObject, true)
    end
    local goodNode = GetLuaBehaviour(trans.gameObject, StoreConstants.GoodNodePath)
    if not isNull(goodNode) then
        goodNode.Env:Reload({ goodsId = data.goodsId, isShowNo = true,
                                text = string.format('x%d', data.goodsNum) })
    end
end

function StoreExchange:OnFragRefresh(listView, index, row, column)
    if index < 0 then
        return nil
    end
    --printInfo(index)
    local cell = listView:NewListViewItem(CellName)
    cell.gameObject:GetComponent(typeof(CS.Game.Native.Common.ReverseScale)):ResetScale()
    --print(table.dump(StoreShared.SettingStores[StoreConstants.OpenIds.StoreItemEntry].children))
    --local list = self.FragDatas[listView.gameObject.name]
    --printInfo(id)
    --printInfo(listView.gameObject.name)
    local data = self.FragDatas[index + 1]
    self:RefreshGoodNode(cell.transform, data)
    return cell
end

return StoreExchange